SELECT jsonb_pretty(jsonb_agg(t ORDER BY t.schema,t.name)) FROM (
SELECT n.nspname AS schema,c.relname AS name,c.relrowsecurity AS rls,c.relkind AS kind,
pg_get_partkeydef(c.oid) AS partition_key,obj_description(c.oid) AS comment,
(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'comment',col_description(c.oid,a.attnum)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped) AS columns,
(SELECT jsonb_agg(jsonb_build_object('name',con.conname,'type',con.contype,'definition',pg_get_constraintdef(con.oid),'columns',(SELECT jsonb_agg(a.attname ORDER BY k.ord) FROM unnest(con.conkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum=k.num),'target',CASE WHEN con.confrelid<>0 THEN con.confrelid::regclass::text ELSE NULL END,'target_columns',(SELECT jsonb_agg(a.attname ORDER BY k.ord) FROM unnest(con.confkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=con.confrelid AND a.attnum=k.num),'delete',con.confdeltype,'update',con.confupdtype) ORDER BY con.conname) FROM pg_constraint con WHERE con.conrelid=c.oid) AS constraints,
(SELECT jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),'primary',i.indisprimary,'unique',i.indisunique,'method',am.amname,'predicate',pg_get_expr(i.indpred,i.indrelid),'keys',(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid,k,true) ORDER BY k) FROM generate_series(1,i.indnkeyatts) k)) ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid JOIN pg_am am ON am.oid=ic.relam WHERE i.indrelid=c.oid) AS indexes
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p') AND NOT c.relispartition AND n.nspname IN ('toca_auth','core','crm','deal','financial','ops','portal','comm','calendar','events','ai','signature','audit','exports')
) t;
